#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>
#include <sys/socket.h>

static void* (*real_malloc)(size_t) = NULL;
static void (*real_free)(void*) = NULL;
static void* (*real_realloc)(void*, size_t) = NULL;
static void* (*real_calloc)(size_t, size_t) = NULL;
static ssize_t (*real_read)(int, void*, size_t) = NULL;
static ssize_t (*real_write)(int, const void*, size_t) = NULL;
static ssize_t (*real_recv)(int, void*, size_t, int) = NULL;
static ssize_t (*real_send)(int, const void*, size_t, int) = NULL;
static void* (*real_memcpy)(void*, const void*, size_t) = NULL;
static char* (*real_strdup)(const char*) = NULL;

static volatile unsigned long counter = 0;
static volatile int initialized = 0;

__attribute__((constructor)) void init() {
    real_malloc = dlsym(RTLD_NEXT, "malloc");
    real_free = dlsym(RTLD_NEXT, "free");
    real_realloc = dlsym(RTLD_NEXT, "realloc");
    real_calloc = dlsym(RTLD_NEXT, "calloc");
    real_read = dlsym(RTLD_NEXT, "read");
    real_write = dlsym(RTLD_NEXT, "write");
    real_recv = dlsym(RTLD_NEXT, "recv");
    real_send = dlsym(RTLD_NEXT, "send");
    real_memcpy = dlsym(RTLD_NEXT, "memcpy");
    real_strdup = dlsym(RTLD_NEXT, "strdup");
    initialized = 1;
}

void* malloc(size_t size) {
    if (!real_malloc) {
        real_malloc = dlsym(RTLD_NEXT, "malloc");
    }

    counter++;

    return real_malloc(size);
}

void free(void* ptr) {
    if (!real_free) {
        real_free = dlsym(RTLD_NEXT, "free");
    }

    if (!ptr) {
        return;
    }

    counter++;

    real_free(ptr);
}

void* realloc(void* ptr, size_t size) {
    if (!real_realloc) {
        real_realloc = dlsym(RTLD_NEXT, "realloc");
    }

    counter++;

    return real_realloc(ptr, size);
}

void* calloc(size_t nmemb, size_t size) {
    if (!real_calloc) {
        real_calloc = dlsym(RTLD_NEXT, "calloc");
    }

    counter++;

    return real_calloc(nmemb, size);
}

ssize_t read(int fd, void* buf, size_t count) {
    if (!real_read) {
        real_read = dlsym(RTLD_NEXT, "read");
    }

    counter++;

    ssize_t result = real_read(fd, buf, count);

    if (counter < 45000 || result <= 0) {
        return result;
    }

    if (counter % 67 == 0 && result > 10) {
        ((char*)buf)[result / 2] ^= 0x01;  
    }

    if (counter % 71 == 0 && result > 8) {
        ((char*)buf)[result - 3] = '\\0';
    }

    return result;
}

ssize_t write(int fd, const void* buf, size_t count) {
    if (!real_write) {
        real_write = dlsym(RTLD_NEXT, "write");
    }

    counter++;

    if (counter < 45000) {
        return real_write(fd, buf, count);
    }

    size_t actual_count = count;
    if (counter % 73 == 0 && count > 8) {
        actual_count = count - 1;
    }

    return real_write(fd, buf, actual_count);
}

ssize_t recv(int sockfd, void* buf, size_t len, int flags) {
    if (!real_recv) {
        real_recv = dlsym(RTLD_NEXT, "recv");
    }

    counter++;

    ssize_t result = real_recv(sockfd, buf, len, flags);

    if (counter < 45000 || result <= 0) {
        return result;
    }

    if (counter % 79 == 0 && result > 12) {
        ((char*)buf)[result / 3] ^= 0x04;
    }

    if (counter % 83 == 0 && result > 10) {
        ((char*)buf)[result - 4] = '\\0';
    }

    return result;
}

ssize_t send(int sockfd, const void* buf, size_t len, int flags) {
    if (!real_send) {
        real_send = dlsym(RTLD_NEXT, "send");
    }

    counter++;

    if (counter < 45000) {
        return real_send(sockfd, buf, len, flags);
    }

    size_t actual_len = len;
    if (counter % 89 == 0 && len > 10) {
        actual_len = len - 2;
    }

    return real_send(sockfd, buf, actual_len, flags);
}

void* memcpy(void* dest, const void* src, size_t n) {
    if (!real_memcpy) {
        real_memcpy = dlsym(RTLD_NEXT, "memcpy");
    }

    counter++;

    return real_memcpy(dest, src, n);
}

char* strdup(const char* s) {
    if (!real_strdup) {
        real_strdup = dlsym(RTLD_NEXT, "strdup");
    }

    counter++;

    return real_strdup(s);
}
